-- GENERATED BY `pnpm codegen` FROM ontology/ontology.yaml -- DO NOT EDIT.

-- The ontology is enforced by the database, not by application convention.
-- An edge with an invalid predicate or a domain/range violation is rejected
-- at write time, in every code path, including ad hoc psql.

ALTER TABLE core.edge DROP CONSTRAINT IF EXISTS edge_predicate_declared;
ALTER TABLE core.edge ADD CONSTRAINT edge_predicate_declared
  CHECK (predicate IN ('aired_on', 'based_on', 'belongs_to_genre', 'broader_than', 'distributed_by', 'explores_theme', 'features_character', 'influenced_by', 'part_of_franchise', 'portrayed_by', 'produced_by', 'remake_of', 'sequel_to'));

ALTER TABLE core.edge_derived DROP CONSTRAINT IF EXISTS edge_derived_predicate_declared;
ALTER TABLE core.edge_derived ADD CONSTRAINT edge_derived_predicate_declared
  CHECK (predicate IN ('similar_to'));

ALTER TABLE core.credit DROP CONSTRAINT IF EXISTS credit_predicate_declared;
ALTER TABLE core.credit ADD CONSTRAINT credit_predicate_declared
  CHECK (predicate IN ('acted_in', 'composed_for', 'directed', 'shot', 'wrote'));

-- Domain/range enforcement, including concept-scheme and organization-kind subtypes.
CREATE OR REPLACE FUNCTION core.assert_edge_valid() RETURNS trigger AS $$
DECLARE ok boolean := false; subtype_ok boolean := true;
BEGIN
  CASE NEW.predicate
    WHEN 'aired_on' THEN
      ok := NEW.subject_type IN ('title')
        AND NEW.object_type IN ('organization');
      IF ok AND NEW.object_type = 'organization' THEN
        SELECT kind IN ('network') INTO subtype_ok
          FROM core.organization WHERE id = NEW.object_id;
      END IF;
    WHEN 'based_on' THEN
      ok := NEW.subject_type IN ('title')
        AND NEW.object_type IN ('work');
    WHEN 'belongs_to_genre' THEN
      ok := NEW.subject_type IN ('title')
        AND NEW.object_type IN ('concept');
      IF ok AND NEW.object_type = 'concept' THEN
        SELECT scheme IN ('genre') INTO subtype_ok
          FROM core.concept WHERE id = NEW.object_id;
      END IF;
    WHEN 'broader_than' THEN
      ok := NEW.subject_type IN ('concept')
        AND NEW.object_type IN ('concept');
    WHEN 'distributed_by' THEN
      ok := NEW.subject_type IN ('title')
        AND NEW.object_type IN ('organization');
      IF ok AND NEW.object_type = 'organization' THEN
        SELECT kind IN ('distributor') INTO subtype_ok
          FROM core.organization WHERE id = NEW.object_id;
      END IF;
    WHEN 'explores_theme' THEN
      ok := NEW.subject_type IN ('title')
        AND NEW.object_type IN ('concept');
      IF ok AND NEW.object_type = 'concept' THEN
        SELECT scheme IN ('theme') INTO subtype_ok
          FROM core.concept WHERE id = NEW.object_id;
      END IF;
    WHEN 'features_character' THEN
      ok := NEW.subject_type IN ('title')
        AND NEW.object_type IN ('character');
    WHEN 'influenced_by' THEN
      ok := NEW.subject_type IN ('title', 'person')
        AND NEW.object_type IN ('title', 'person');
    WHEN 'part_of_franchise' THEN
      ok := NEW.subject_type IN ('title')
        AND NEW.object_type IN ('collection');
    WHEN 'portrayed_by' THEN
      ok := NEW.subject_type IN ('character')
        AND NEW.object_type IN ('person');
    WHEN 'produced_by' THEN
      ok := NEW.subject_type IN ('title')
        AND NEW.object_type IN ('organization');
      IF ok AND NEW.object_type = 'organization' THEN
        SELECT kind IN ('studio', 'production') INTO subtype_ok
          FROM core.organization WHERE id = NEW.object_id;
      END IF;
    WHEN 'remake_of' THEN
      ok := NEW.subject_type IN ('title')
        AND NEW.object_type IN ('title');
    WHEN 'sequel_to' THEN
      ok := NEW.subject_type IN ('title')
        AND NEW.object_type IN ('title');
    WHEN 'similar_to' THEN
      ok := NEW.subject_type IN ('title')
        AND NEW.object_type IN ('title');
    ELSE
      RAISE EXCEPTION 'predicate % is not declared in ontology.yaml', NEW.predicate;
  END CASE;
  IF NOT ok THEN
    RAISE EXCEPTION 'ontology violation: % (% -> %) breaks the declared domain/range',
      NEW.predicate, NEW.subject_type, NEW.object_type;
  END IF;
  IF NOT coalesce(subtype_ok, false) THEN
    RAISE EXCEPTION 'ontology violation: % object fails its declared subtype constraint', NEW.predicate;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

